+                if (view == focused || view == recycler) {
+                    continue;
+                }
+
+                int candidate = getDistance(sourcePosition, view, listDirection);
+                if (candidate < 0) {
+                    continue;
+                }
+
+                if (candidate < distance) {
+                    distance = candidate;
+                    preferred = view;
+                }
+            }
+        } finally {
+            focusables.clear();
+        }
+
