+            case View.FOCUS_FORWARD:
+                return 1;
+            case View.FOCUS_BACKWARD:
+                return -1;
+        }
+
+        if (getOrientation() == RecyclerView.HORIZONTAL) {
+            switch (direction) {
+                default:
+                    break;
+                case View.FOCUS_LEFT:
+                    return getReverseLayout() ? 1 : -1;
+                case View.FOCUS_RIGHT:
+                    return getReverseLayout() ? -1 : 1;
+            }
+        } else {
+            switch (direction) {
+                default:
+                    break;
+                case View.FOCUS_UP:
+                    return getReverseLayout() ? 1 : -1;
+                case View.FOCUS_DOWN:
+                    return getReverseLayout() ? -1 : 1;
+            }
+        }
